  'GGGGGG',
  'GGYYGG',
  'GYGGYG'
];

function buildCols(grid) {
  const cols = [[], [], [], [], [], []];
  for (let r = 0; r < grid.length; r++) {
    for (let c = 0; c < 6; c++) cols[c].push(grid[r][c]);
  }
  return cols;
}

function getBottomGroupCount(col) {
  if (col.length === 0) return 0;
  const color = col[col.length - 1];
  let k = 0;
  for (let i = col.length - 1; i >= 0; i--) {
    if (col[i] === color) k++; else break;
  }
  return k;
}

function getTotalRem(cols, color) {
  let t = 0;
  for (const col of cols) for (const c of col) if (c === color) t++;
  return t;
}

function getTarget(cols, color) {
  return Math.min(MAX_BATCH, Math.max(1, getTotalRem(cols, color)));
}

function findTarget(cols, color, startIdx) {
  const n = cols.length;
  for (let s = 1; s < n; s++) {
    const idx = (startIdx + s) % n;
    if (cols[idx].length > 0 && cols[idx][cols[idx].length - 1] === color) return idx;
  }
  for (let s = 1; s < n; s++) {
    const idx = (startIdx + s) % n;
    if (cols[idx].length === 0) return idx;
  }
  return -1;
}

function stepCol(cols, colIdx) {
  const col = cols[colIdx];
  if (col.length === 0) return null;
  const count = getBottomGroupCount(col);
  const color = col[col.length - 1];
  const t = findTarget(cols, color, colIdx);
